	/** 
	 * jumpstart the process by instantiating2 Metric
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		metricId = MetricService.getMetricInstance()
		.createMetric( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		MetricService.getMetricInstance()
				.createMetric( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.metricSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Metric : " + successValue.getMetricId());
							  if (successValue.getMetricId().equals(metricId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfMetricList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Metric test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on metric consumed")
					);
			subscriber.metricSubscribe( metricId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Metric : " + successValue.getMetricId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfMetricList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on metric for metricId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Metric. 
	 */
	protected Metric read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Metric" );

		Metric entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Metric with primary key" );
		msg.append( metricId );
		
		MetricFetchOneSummary fetchOneSummary = new MetricFetchOneSummary( metricId );

		try {
			entity = MetricService.getMetricInstance().getMetric( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Metric " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Metric.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Metric." );

		StringBuilder msg = new StringBuilder( "Failed to update a Metric : " );        
		Metric entity = read();
		UpdateMetricCommand command = generateUpdateCommand();
		command.setMetricId(entity.getMetricId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Metric." );

			// for use later on...
			metricId = entity.getMetricId();

			MetricService proxy = MetricService.getMetricInstance();  

			proxy.updateMetric( command ).get();

			LOGGER.info( "-- Successfully saved Metric - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + metricId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Metric.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Metric." );

		Metric entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Metric with id " + metricId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Metric with id " + metricId );

			throw e;
		}

		try{
			MetricService.getMetricInstance().delete( new DeleteMetricCommand( entity.getMetricId() ) ).get();
			LOGGER.info( "-- Successfully deleted Metric with id " + metricId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Metric with id " + metricId );

			throw e;
		}
	}

	/**
	 * get all Metrics.
	 */
	protected List<Metric> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Metrics:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Metric : " );        
		List<Metric> collection  = new ArrayList<>();

		try {
			// call the static get method on the MetricService
			collection = MetricService.getMetricInstance().getAllMetric();
			assertNotNull( collection, "An Empty collection of Metric was incorrectly returned.");
			
			// Now print out the values
			Metric entity = null;            
			Iterator<Metric> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getMetricId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

